import{_ as i,a0 as p,w as l,s as a,ao as u,I as s,x as e,a1 as r,A as o}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const C=JSON.parse('{"title":"戴文的Linux內核專題：02 源代碼 | LCTT x X-CMD","titleTemplate":false,"description":"戴文的Linux內核專題：02 源代碼 | LCTT (The Linux Kernel) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"戴文的Linux內核專題：02 源代碼 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"戴文的Linux內核專題：02 源代碼 | LCTT (The Linux Kernel) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"The Linux Kernel/02 The Linux Kernel--The Source Code","title":"戴文的Linux內核專題：02 源代碼","tag":"The Linux Kernel","desc":""},"relativePath":"The Linux Kernel/02 The Linux Kernel--The Source Code.md","filePath":"[post].md"}'),g={name:"The Linux Kernel/02 The Linux Kernel--The Source Code.md"};function x(m,n,d,h,c,T){const t=p("Link");return l(),a("div",null,[n[11]||(n[11]=u(`<h1 id="戴文的linux內核專題-02-源代碼" tabindex="-1">戴文的Linux內核專題：02 源代碼 <a class="header-anchor" href="#戴文的linux內核專題-02-源代碼" aria-label="Permalink to “戴文的Linux內核專題：02 源代碼”">​</a></h1><p>在下載並解壓內核源代碼後，用户可以看到許多文件夾和文件。嘗試去找一個特定的文件或許是一個挑戰。謝天謝地，源代碼以一個特定的方式組織的。這使開發者能夠輕鬆找到任何文件或者內核的一部分。</p><p>內核源代碼的根目錄下包含了以下文件夾</p><pre><code>arch
block
crypto
Documentation
drivers
firmware
fs
include
init
ipc
kernel
lib
mm
net
samples
scripts
security
sound
tools
usr
virt
</code></pre><p>還有一些文件在源代碼的根目錄下。它們會在下面列出。</p><p><strong>COPYING</strong> -許可和授權信息。Linux內核在GPLv2許可證下授權。該許可證授予任何人有權免費去使用、修改、分發和共享源代碼和編譯代碼。然而，沒有人可以出售源代碼。</p><p><strong>CREDITS</strong> - 貢獻者列表</p><p><strong>Kbuild</strong> - 這是一個設置一些內核設定的腳本。打個比方，這個腳本設定一個ARCH變量，這是開發者想要生成的內核支持的處理器類型。</p><p><strong>Kconfig</strong> - 這個腳本會在開發人員配置內核的時候用到，這會在以後的文章中討論。</p><p><strong>MAINTAINERS</strong> - 這是一個目前維護者列表，他們的電子郵件地址，主頁，和他們負責開發和維護的內核的特定部分或文件。當一個開發者在內核中發現一個問題，並希望能夠報告給能夠處理這個問題的維護者時，這是是很有用的。</p><p><strong>Makefile</strong> - This script is the main file that is used to compile the kernel. This file passes parameters to the compiler as well as the list of files to compile and any other necessary information. 這個腳本是編譯內核的主要文件。這個文件將編譯參數和編譯所需的文件和必要的信息傳給編譯器。</p><p><strong>README</strong> - 這個文檔提供給開發者想要知道的如何編譯內核的信息。</p><p><strong>REPORTING-BUGS</strong> - 這個文檔提供如何報告問題的信息。</p><p>內核的代碼是以“.c”或“.h”為擴展名的文件。 “.c”的擴展名表明內核是用眾多的編程語言之一的C語言寫的， “h”的文件是頭文件，而他們也是用C寫成。頭文件包含了許多“.c”文件需要使用的代碼，因為他們可以引入已有的代碼而不是重新編寫代碼，這節省了程序員的時間。否則，一組執行相同的動作的代碼，將存在許多或全部都是“c”文件。這也會消耗和浪費硬盤空間。（譯註：頭文件不僅僅可節省重複編碼，而且代碼複用也會降低代碼錯誤的幾率）</p><p>所有上面列出的文件夾中的文件都組織得很好。文件夾名稱至少可以幫助開發人員很好地猜測文件夾中的內容。下面提供了一個目錄樹和描述。</p><p><strong>arch</strong> - 這個文件夾包含了一個Kconfig文件，它用於設置這個目錄裏的源代碼編譯所需的一系列設定。每個支持的處理器架構都在它相應的文件夾中。如，Alpha處理器的源代碼在alpha文件夾中。請記住，隨着時間的推移，一些新的處理器將被支持,有些會被放棄。對於Linux v3.9.4，arch下有以下文件夾：</p><pre><code>alpha
arc
arm
arm64
avr32
blackfin
c6x
cris
frv
h8300
hexagon
ia64
m32r
m68k
metag
microblaze
mips
mn10300
openrisc
parisc
powerpc
s390
score
sh
sparc
tile
um
unicore32
x86
xtensa
</code></pre><p><strong>block</strong> – 此文件夾包含塊設備驅動程序的代碼。塊設備是以數據塊方式接收和發送的數據的設備。數據塊都是一塊一塊的數據而不是持續的數據流。</p><p><strong>crypto</strong> - 這個文件夾包含許多加密算法的源代碼。例如，“sha1_generic.c”這個文件包含了SHA1加密算法的代碼。</p><p><strong>Documentation</strong> - 此文件夾包含了內核信息和其他許多文件信息的文本文檔。如果開發者需要一些信息，他們也許能在這裏找到所需要的信息。</p><p><strong>drivers</strong> - 該目錄包含了驅動代碼。驅動是一個控制硬件的軟件。例如，要讓計算機知道鍵盤並使其可用，鍵盤驅動是必要的。這個文件夾中存在許多文件夾。每個文件夾都以硬件的種類或者型號命名。例如，&#39;bluetooth&#39;包含了藍牙驅動程序的代碼。還有其他很明顯的驅動像SCSI、USB和火線等。有些驅動程序可能會比較難找到。例如，操縱桿驅動不在&#39;joystick&#39;文件夾中，它們卻在./drivers/input/joystick。同樣鍵盤和鼠標驅動也在這個input文件夾中。 &#39;Macintosh&#39;包含了蘋果的硬件代碼。 &#39;Xen&#39;包含了Xen hypervisor代碼。（hypervisor是一種允許用户在一台計算機上運行多個操作系統的軟件或硬件。這意味着在Xen允許用户在一台計算機上同時運行的兩個或兩個以上的Linux系統。用户還可以運行Windows，Solaris，FreeBSD或其他操作系統在Linux系統上。）driver文件夾下還有許多其他的文件夾，但他們在這篇文章中無法一一列舉，他們將在以後的文章中提到。</p><p><strong>firmware</strong> - fireware中包含了讓計算機讀取和理解從設備發來的信號的代碼。舉例來説，一個攝像頭管理它自己的硬件，但計算機必須瞭解攝像頭給計算機發送的信號。Linux系統會使用vicam固件（firmware）來理解攝像頭的通訊。否則，沒有了固件，Linux系統將不知道如何處理攝像頭髮來的信息。另外，固件同樣有助於將Linux系統發送消息給該設備。這樣Linux系統可以告訴攝像頭重新調整或關閉攝像頭。</p><p><strong>fs</strong> - 這是文件系統的文件夾。理解和使用的文件系統所需要的所有的代碼就在這裏。在這個文件夾裏，每種文件系統都有自己的文件夾。例如，ext4文件系統的代碼在ext4文件夾內。 在fs文件夾內，開發者會看到一些不在文件夾中的文件。這些文件用來控制整個文件系統。例如，mount.h中會包含掛載文件系統的代碼。文件系統是以結構化的方式來存儲和管理的存儲設備上的文件和目錄。每個文件系統都有自己的優點和缺點。這是由文件系統的設計決定的。舉例來説，NTFS文件系統支持的透明壓縮（當啓用時，會在用户不知道的情況下自動壓縮存儲文件）。大多數文件系統缺乏此功能，但如果在fs文件夾裏編入相應的文件，它們也有這種能力。</p><p><strong>include</strong> - include包含了內核所需的各種頭文件.這個名字來自於C語言用&quot;include&quot;來在編譯時導入頭文件。</p><p><strong>init</strong> - init文件夾包含了內核啓動的處理代碼(INITiation)。main.c是內核的核心文件，這是用來銜接所有的其他文件的源代碼主文件。</p><p><strong>ipc</strong> - IPC代表進程間通訊。此文件夾中的代碼是作為內核與進程之間的通信層。內核控制着硬件，因此程序只能請求內核來執行任務。假設用户有一個打開DVD托盤的程序。程序不直接打開托盤，相反，該程序通知內核托盤應該被打開。然後，內核給硬件發送一個信號去打開托盤。這些代碼同樣管理kill信號。舉例來説，當系統管理員打開進程管理器去關閉一個已經鎖死的程序，這個關閉程序的信號被稱為kill信號。內核接收到信號，然後內核會要求程序停止或直接把進程從內存和CPU中移除（取決於kill的類型）。命令列中的管道同樣用於進程間通信。管道會告訴內核在某個內存頁上寫入輸出數據。程序或者命令得到的數據是來自內存頁上的某個給定的指針。</p><p><strong>kernel</strong> - 這個文件夾中的代碼控制內核本身。例如，如果一個調試器需要跟蹤問題，內核將使用這個文件夾中代碼來將內核指令通知調試器跟蹤內核進行的所有動作。這裏也有跟蹤時間的代碼。在內核文件夾下有個&quot;power&quot;文件夾，這裏的代碼可以使計算機重新啓動、關機和掛起。</p><p><strong>lib</strong> - 這個文件夾包含了內核需要引用的一系列內核庫文件代碼。</p><p><strong>mm</strong> - mm文件夾中包含了內存管理代碼。內存並不是任意存儲在RAM芯片上的。相反，內核小心地將數據放在RAM芯片上。內核不會覆蓋任何正在使用或保存重要數據的內存區域。</p><p><strong>net</strong> - net文件夾中包含了網絡協議代碼。這包括IPv6、AppleTalk、以太網、WiFi、藍牙等的代碼，此外處理網橋和DNS解析的代碼也在net目錄。</p><p><strong>samples</strong> - 此文件夾包含了程序示例和正在編寫中的模組代碼。假設一個新的模組引入了一個想要的有用功能，但沒有程序員説它已經可以正常運行在內核上。那麼，這些模組就會移到這裏。這給了新內核程序員一個機會通過這個文件夾來獲得幫助，或者選擇一個他們想要協助開發的模組。</p><p><strong>scripts</strong> - 這個文件夾有內核編譯所需的腳本。最好不要改變這個文件夾內的任何東西。否則，您可能無法配置或編譯內核。</p><p><strong>security</strong> - 這個文件夾是有關內核安全的代碼。它對計算機免於受到病毒和黑客的侵害很重要。否則，Linux系統可能會遭到損壞。關於內核的安全性，將在以後的文章中討論。</p><p><strong>sound</strong> - 這個文件夾中包含了聲卡驅動。</p><p><strong>tools</strong> - 這個文件夾中包含了和內核交互的工具。</p><p><strong>usr</strong> - 還記得在以前的文章中提到vmlinuz和其他類似的文件麼？這個文件夾中的代碼在內核編譯完成後創建這些文件。</p><p><strong>virt</strong> - 此文件夾包含了虛擬化代碼，它允許用户一次運行多個操作系統。這與先前提到的Xen是不同的。通過虛擬化，客户機操作系統就像任何其他運行在Linux主機的應用程序一樣運行。通過Xen這樣的hypervisor(注:虛擬機管理程序)，兩個操作系統可以同時管理硬件。在虛擬化中，在客户機操作系統上運行在Linux內核上，而在hypervisor中，它沒有客户系統並且所有的系統不互相依賴。</p><p>提示: 絕不在內核源代碼內移動文件，除非你知道你在做什麼。否則，編譯會由於缺失文件失敗。</p><p>Linux內核的文件夾結構保持相對穩定。內核開發者會做一些修改，但總體來説，這些設置對整個內核版本都是一樣。驅動程序文件夾的佈局也基本保持一樣。</p><hr>`,40)),s("p",null,[n[1]||(n[1]=e("via: ",-1)),r(t,{href:"http://www.linux.org/threads/the-linux-kernel-the-source-code.4204/"},{default:o(()=>[...n[0]||(n[0]=[e("http://www.linux.org/threads/the-linux-kernel-the-source-code.4204/",-1)])]),_:1})]),s("p",null,[n[4]||(n[4]=e("譯者：",-1)),r(t,{href:"https://github.com/geekpi"},{default:o(()=>[...n[2]||(n[2]=[e("geekpi",-1)])]),_:1}),n[5]||(n[5]=e(" 校對：",-1)),r(t,{href:"https://github.com/wxy"},{default:o(()=>[...n[3]||(n[3]=[e("wxy",-1)])]),_:1})]),s("p",null,[n[8]||(n[8]=e("本文由 ",-1)),r(t,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...n[6]||(n[6]=[e("LCTT",-1)])]),_:1}),n[9]||(n[9]=e(" 原創翻譯，",-1)),r(t,{href:"http://linux.cn/"},{default:o(()=>[...n[7]||(n[7]=[e("Linux中國",-1)])]),_:1}),n[10]||(n[10]=e(" 榮譽推出",-1))])])}const k=i(g,[["render",x]]);export{C as __pageData,k as default};
